import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

// 가정: 알림 채널은 기본 채널인 포털로 발송한다.
const NOTIFY_CHANNEL = '포털';

function pathId(value: string | undefined): string {
  if (typeof value !== 'string' || !/^\d+$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '인사발령 ID 형식이 올바르지 않습니다.');
  }
  return value;
}

function optionalText(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01301Controller {
  @Post('/personnel-appointments/:personnelAppointmentId/approve')
  @HttpCode(200)
  async approvePersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = pathId(req.params['personnelAppointmentId']);
    const data = checks.inputOf(req.body);
    const comment = optionalText(data['reviewComment'], '검토 의견');
    return transaction(async (db) => {
      return this.decide(db, id, user.id, '승인', null, comment);
    });
  }

  @Post('/personnel-appointments/:personnelAppointmentId/reject')
  @HttpCode(200)
  async rejectPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = pathId(req.params['personnelAppointmentId']);
    const data = checks.inputOf(req.body);
    const comment = optionalText(data['reviewComment'], '검토 의견');
    const reason = optionalText(data['rejectReason'], '반려 사유');
    if (reason === null || reason.trim() === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      return this.decide(db, id, user.id, '반려', reason, comment);
    });
  }

  private async decide(
    db: Db,
    id: string,
    userId: string,
    toStatus: '승인' | '반려',
    rejectReason: string | null,
    comment: string | null,
  ) {
    const found = await db.query(
      'SELECT personnel_appointment_id AS "personnelAppointmentId", status, approval_document_id AS "approvalDocumentId" FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint) FOR UPDATE',
      { id },
    );
    if (found.length === 0) {
      throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령 신청 건을 찾을 수 없습니다.');
    }
    const current = found[0];
    if (current['status'] !== '신청') {
      throw new ApiError(409, 'PERSONNEL_APPOINTMENT_STATUS_MISMATCH', '신청 상태인 건만 처리할 수 있습니다.');
    }

    const updated = await db.query(
      'UPDATE personnel_appointment SET status = :status, reject_reason = :rejectReason, processed_by = CAST(:userId AS bigint), processed_at = now(), updated_at = now() WHERE personnel_appointment_id = CAST(:id AS bigint) AND status = :fromStatus RETURNING personnel_appointment_id AS "personnelAppointmentId", status',
      { id, status: toStatus, rejectReason, userId, fromStatus: '신청' },
    );
    if (updated.length === 0) {
      throw new ApiError(409, 'PERSONNEL_APPOINTMENT_STATUS_MISMATCH', '신청 상태인 건만 처리할 수 있습니다.');
    }

    const content = '발령 상태 신청 → ' + toStatus + (comment ? ' (검토 의견: ' + comment + ')' : '');
    await db.execute(
      'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, change_reason, created_at, updated_at) VALUES (CAST(:userId AS bigint), :targetType, CAST(:id AS bigint), :changeType, now(), :content, :reason, now(), now())',
      {
        userId,
        targetType: 'personnel_appointment',
        id,
        changeType: toStatus,
        content,
        reason: rejectReason,
      },
    );

    // 가정: 신청자는 연결된 전자결재 문서의 기안자로 본다.
    if (current['approvalDocumentId'] !== null && current['approvalDocumentId'] !== undefined) {
      const drafters = await db.query(
        'SELECT drafter_id AS "drafterId" FROM approval_document WHERE approval_document_id = CAST(:docId AS bigint)',
        { docId: String(current['approvalDocumentId']) },
      );
      if (drafters.length > 0) {
        await db.execute(
          'INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at) VALUES (CAST(:recipientId AS bigint), :channel, :title, :content, :readStatus, :eventType, :targetType, CAST(:id AS bigint), now(), now())',
          {
            recipientId: String(drafters[0]['drafterId']),
            channel: NOTIFY_CHANNEL,
            title: '인사발령 신청이 ' + toStatus + '되었습니다.',
            content: rejectReason ?? comment,
            readStatus: '안읽음',
            eventType: toStatus === '승인' ? 'PERSONNEL_APPOINTMENT_APPROVED' : 'PERSONNEL_APPOINTMENT_REJECTED',
            targetType: 'PERSONNEL_APPOINTMENT',
            id,
          },
        );
      }
    }

    return updated[0];
  }
}

