import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  Pairs,
  RefName,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

type Mode = 'approve' | 'reject';

export default function FnSfr01301Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<{ mode: Mode; row: Row } | null>(null);
  const [reviewComment, setReviewComment] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const list = useData<Page>(async () => {
    if (applied === '') {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/personnel-appointments', role, undefined, {
      employeeId: applied,
      page: pageNo,
      size: 20,
    });
  }, [applied, pageNo, role]);

  const open = (mode: Mode, row: Row) => {
    setReviewComment('');
    setRejectReason('');
    setTarget({ mode, row });
  };

  const submit = async () => {
    if (!target) {
      return;
    }
    const id = target.row['personnelAppointmentId'];
    if (target.mode === 'reject') {
      if (rejectReason.trim() === '') {
        throw new Error('반려 사유를 입력해 주세요.');
      }
      await call('POST', `/personnel-appointments/${id}/reject`, role, {
        rejectReason,
        reviewComment,
      });
      notify('반려했습니다.');
    } else {
      await call('POST', `/personnel-appointments/${id}/approve`, role, {
        reviewComment,
      });
      notify('승인했습니다.');
    }
    setTarget(null);
    list.reload();
  };

  const columns = [
    {
      key: 'departmentId',
      label: '발령 후 부서',
      render: (r: Row) => <RefName table="department" role={role} value={r['departmentId']} />,
    },
    { key: 'appointmentType', label: '발령 구분' },
    {
      key: 'appointmentDate',
      label: '발령일자',
      render: (r: Row) => <DateText value={r['appointmentDate']} />,
    },
    {
      key: 'status',
      label: '발령 상태',
      render: (r: Row) => <Badge value={r['status']} />,
    },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) =>
        r['status'] === '신청' ? (
          <span>
            <button type="button" onClick={() => open('approve', r)}>
              승인
            </button>
            <button type="button" className="ghost" onClick={() => open('reject', r)}>
              반려
            </button>
          </span>
        ) : null,
    },
  ];

  const page = list.data;

  return (
    <div>
      <h1>인사발령 신청 검토·승인</h1>
      <Filters
        onSearch={() => {
          setPageNo(0);
          setApplied(employeeId);
        }}
        onReset={() => {
          setEmployeeId('');
          setApplied('');
          setPageNo(0);
        }}
      >
        <Field label="발령 대상 임직원" required>
          <LookupSelect
            table="employee"
            role={role}
            value={employeeId}
            onChange={setEmployeeId}
            placeholder="임직원 선택"
          />
        </Field>
      </Filters>
      <Band total={page ? page.total : 0} />
      {list.error ? <p>{list.error}</p> : null}
      <DataTable
        columns={columns}
        rows={page ? page.items : []}
        empty={
          applied === ''
            ? '발령 대상 임직원을 고른 뒤 조회해 주세요.'
            : '신청된 인사발령 내역이 없습니다.'
        }
      />
      {page ? (
        <Pager page={page.page} size={page.size} total={page.total} onPage={setPageNo} />
      ) : null}
      {target ? (
        <Drawer
          title={target.mode === 'approve' ? '인사발령 신청 승인' : '인사발령 신청 반려'}
          onClose={() => setTarget(null)}
        >
          <Pairs
            items={[
              [
                '발령 후 부서',
                <RefName table="department" role={role} value={target.row['departmentId']} />,
              ],
              ['발령 구분', String(target.row['appointmentType'] ?? '')],
              ['발령일자', <DateText value={target.row['appointmentDate']} />],
              ['발령 후 직위·직책', String(target.row['positionAfter'] ?? '')],
              ['발령 상태', <Badge value={target.row['status']} />],
            ]}
          />
          <Form
            onSubmit={submit}
            submit={target.mode === 'approve' ? '승인' : '반려'}
            danger={target.mode === 'reject'}
            note={
              target.mode === 'reject'
                ? '반려하면 신청자에게 알림이 가고 다시 승인할 수 없습니다.'
                : '승인하면 신청자에게 알림이 갑니다.'
            }
          >
            {target.mode === 'reject' ? (
              <Field label="반려 사유" required wide>
                <TextInput value={rejectReason} onChange={setRejectReason} multiline />
              </Field>
            ) : null}
            <Field label="검토 의견" wide>
              <TextInput value={reviewComment} onChange={setReviewComment} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
